plugins {
    id 'java'
    id 'org.springframework.boot' version '4.1.1'
    id 'io.spring.dependency-management' version '1.1.7'
}

group = 'org.example'
version = '0.0.1-SNAPSHOT'

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

repositories {
    mavenCentral()
}

dependencies {
    // start.spring.io에서 고른 것: Spring Web · Spring Data JPA · Validation · MySQL Driver · Flyway Migration
    implementation 'org.springframework.boot:spring-boot-starter-webmvc'
    implementation 'org.springframework.boot:spring-boot-starter-data-jpa'
    implementation 'org.springframework.boot:spring-boot-starter-validation'
    implementation 'org.springframework.boot:spring-boot-starter-flyway'
    implementation 'org.mybatis.spring.boot:mybatis-spring-boot-starter:4.1.0'
    // 10-3 비밀번호 해시(BCrypt) — Spring Security 전체가 아니라 암호화 모듈만
    implementation 'org.springframework.security:spring-security-crypto'
    // 10-4 JWT 발급·검증(jjwt) — api는 컴파일에, 구현·JSON 처리는 실행할 때만
    implementation 'io.jsonwebtoken:jjwt-api:0.13.0'
    runtimeOnly 'io.jsonwebtoken:jjwt-impl:0.13.0'
    runtimeOnly 'io.jsonwebtoken:jjwt-jackson:0.13.0'
    runtimeOnly 'com.mysql:mysql-connector-j'
    runtimeOnly 'org.flywaydb:flyway-mysql'

    testImplementation 'org.springframework.boot:spring-boot-starter-webmvc-test'
    testRuntimeOnly 'org.junit.platform:junit-platform-launcher'
}

tasks.named('test') {
    useJUnitPlatform()
}

package org.example.board.post;

import java.time.LocalDateTime;
import java.util.List;

public record PostListItemResponse(
        Long id,
        String title,
        String visibility,
        int viewCount,
        int likeCount,
        AuthorResponse author,
        List<String> tags,
        LocalDateTime createdAt) {

    static PostListItemResponse of(Post post, List<String> tags) {
        return new PostListItemResponse(post.getId(), post.getTitle(), post.getVisibility().name(), post.getViewCount(),
                post.getLikeCount(), AuthorResponse.from(post.getAuthor()), tags, post.getCreatedAt());
    }

    static PostListItemResponse of(PostListRow row, List<String> tags) {
        return new PostListItemResponse(row.id, row.title, row.visibility, row.viewCount, row.likeCount,
                new AuthorResponse(row.authorId, row.authorNickname), tags, row.createdAt);
    }
}

package org.example.board.post;

import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

import org.example.board.common.ApiException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

// 게시글 목록·검색 — MyBatis 동적 SQL
@Service
public class PostQueryService {
    private final PostQueryMapper mapper;

    public PostQueryService(PostQueryMapper mapper) {
        this.mapper = mapper;
    }

    @Transactional(readOnly = true)
    public Object list(PostListQuery query, Long loginUserId) {
        if (query.cursorMode()) {
            return cursorList(query, loginUserId);
        }
        int page = query.page() == null ? 0 : query.page();
        long offset = (long) page * query.size();
        List<PostListRow> rows = mapper.findPage(query, loginUserId, offset);
        long total = mapper.count(query, loginUserId);
        return new PageResponse<>(withTags(rows), page, query.size(), total, offset + rows.size() < total);
    }

    private CursorResponse<PostListItemResponse> cursorList(PostListQuery query, Long loginUserId) {
        // 인기순은 좋아요가 바뀌면 순서가 흔들려 커서가 글을 빠뜨리거나 두 번 준다 — 최신순만 허락한다
        if ("popular".equals(query.sort())) {
            throw ApiException.invalid("cursor", "커서 페이징은 최신순(latest)에서만 쓸 수 있습니다.");
        }
        if (query.page() != null) {
            throw ApiException.invalid("page", "page와 cursor는 함께 쓸 수 없습니다.");
        }
        Long cursorId = parseCursor(query.cursor());
        // size + 1행으로 다음 페이지 존재 여부를 판단한다.
        List<PostListRow> rows = mapper.findAfterCursor(query, loginUserId, cursorId, query.size() + 1);
        boolean hasNext = rows.size() > query.size();
        List<PostListRow> page = hasNext ? rows.subList(0, query.size()) : rows;
        String next = hasNext ? String.valueOf(page.get(page.size() - 1).id) : null;
        return new CursorResponse<>(withTags(page), next);
    }

    private Long parseCursor(String cursor) {
        if (cursor.isBlank()) {
            return null;
        }
        try {
            return Long.valueOf(cursor);
        } catch (NumberFormatException e) {
            throw ApiException.invalid("cursor", "커서 값이 올바르지 않습니다.");
        }
    }

    // 글과 태그를 JOIN한 채 페이징하지 않는다 — 이번 페이지 글들의 태그를 IN 한 번으로 읽는다.
    private List<PostListItemResponse> withTags(List<PostListRow> rows) {
        if (rows.isEmpty()) {
            return List.of();
        }
        Map<Long, List<String>> tagsByPost = mapper.findTagsByPostIds(rows.stream().map(row -> row.id).toList())
                .stream()
                .collect(Collectors.groupingBy(PostTagRow::postId, Collectors.mapping(PostTagRow::name, Collectors.toList())));
        return rows.stream()
                .map(row -> PostListItemResponse.of(row, tagsByPost.getOrDefault(row.id, List.of())))
                .toList();
    }
}

package org.example.board.post;

import java.time.LocalDateTime;

// 목록 SQL의 평평한 한 행. author는 응답 DTO에서 다시 중첩한다.
public class PostListRow {
    public Long id;
    public String title;
    public String visibility;
    public int viewCount;
    public int likeCount;
    public Long authorId;
    public String authorNickname;
    public LocalDateTime createdAt;
}

package org.example.board.post;

import java.util.List;
import org.apache.ibatis.annotations.Mapper;
import org.apache.ibatis.annotations.Param;

@Mapper
public interface PostQueryMapper {
    List<PostListRow> findPage(@Param("cond") PostListQuery cond, @Param("loginUserId") Long loginUserId,
            @Param("offset") long offset);

    long count(@Param("cond") PostListQuery cond, @Param("loginUserId") Long loginUserId);

    List<PostListRow> findAfterCursor(@Param("cond") PostListQuery cond, @Param("loginUserId") Long loginUserId,
            @Param("cursorId") Long cursorId, @Param("limit") int limit);

    List<PostTagRow> findTagsByPostIds(@Param("postIds") List<Long> postIds);
}
